import sys
import time
import threading

from shiny import App, ui, render, reactive, Inputs, Outputs, Session
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import pandas as pd
import numpy as np

# Detect Pyodide environment
def is_pyodide():
    try:
        import js  # pyodide-specific
        return True
    except ImportError:
        return False

# Fake psutil for Pyodide
class FakePsutil:
    def __init__(self):
        self._usage = 0.0

    def cpu_percent(self, interval=None):
        # Simulate CPU usage with a sine wave + noise
        t = time.time()
        usage = 50 + 40 * np.sin(t / 5) + np.random.normal(0, 5)
        return max(0, min(100, usage))

if is_pyodide():
    psutil = FakePsutil()
else:
    import psutil

# Hide axis ticks utility
def hide_ticks(ax):
    ax.set_xticks([])
    ax.set_yticks([])

# UI
colormaps = sorted(m for m in plt.colormaps() if not m.endswith("_r"))

app_ui = ui.page_fluid(
    ui.h2("CPU Usage Monitor"),
    ui.layout_sidebar(
        ui.panel_sidebar(
            ui.input_select("colormap", "Colormap", choices=colormaps, selected="viridis"),
            ui.input_numeric("samples", "Samples per graph", 30, min=5, max=200),
            ui.input_numeric("rows", "Rows in table", 10, min=1, max=200),
            ui.input_checkbox("freeze", "Freeze output", False),
            ui.input_action_button("clear", "Clear History"),
            ui.hr(),
            ui.p("Monitor your CPU usage in real time. Works in both standard Python and Pyodide environments."),
        ),
        ui.panel_main(
            ui.output_plot("cpu_plot"),
            ui.output_data_frame("cpu_table"),
        ),
    ),
)

# Server logic
def server(input: Inputs, output: Outputs, session: Session):
    # Store CPU usage history
    cpu_history = reactive.Value(pd.DataFrame(columns=["Timestamp", "CPU Usage"]))

    # Background thread for polling CPU usage (only in standard Python)
    def poll_cpu():
        while True:
            if not input.freeze():
                df = cpu_history()
                usage = psutil.cpu_percent(interval=None)
                now = pd.Timestamp.now()
                new_row = pd.DataFrame({"Timestamp": [now], "CPU Usage": [usage]})
                df = pd.concat([df, new_row], ignore_index=True)
                # Limit history to 1000 samples
                if len(df) > 1000:
                    df = df.iloc[-1000:]
                cpu_history.set(df)
            time.sleep(1)

    if not is_pyodide():
        threading.Thread(target=poll_cpu, daemon=True).start()

    # In Pyodide, use a reactive timer
    @reactive.effect
    @reactive.periodic(1000)
    def _pyodide_poll():
        if is_pyodide():
            if not input.freeze():
                df = cpu_history()
                usage = psutil.cpu_percent(interval=None)
                now = pd.Timestamp.now()
                new_row = pd.DataFrame({"Timestamp": [now], "CPU Usage": [usage]})
                df = pd.concat([df, new_row], ignore_index=True)
                if len(df) > 1000:
                    df = df.iloc[-1000:]
                cpu_history.set(df)

    @reactive.Effect
    @reactive.event(input.clear)
    def _clear_history():
        cpu_history.set(pd.DataFrame(columns=["Timestamp", "CPU Usage"]))

    @output
    @render.plot
    def cpu_plot():
        df = cpu_history()
        n = int(input.samples())
        cmap = input.colormap()
        if len(df) == 0:
            fig, ax = plt.subplots(figsize=(6, 3))
            ax.text(0.5, 0.5, "No data", ha="center", va="center")
            hide_ticks(ax)
            return fig
        df_plot = df.iloc[-n:]
        fig, ax = plt.subplots(figsize=(6, 3))
        norm = plt.Normalize(df_plot["CPU Usage"].min(), df_plot["CPU Usage"].max())
        colors = plt.get_cmap(cmap)(norm(df_plot["CPU Usage"]))
        ax.bar(df_plot["Timestamp"].dt.strftime("%H:%M:%S"), df_plot["CPU Usage"], color=colors)
        ax.set_ylabel("CPU Usage (%)")
        ax.set_xlabel("Time")
        ax.set_ylim(0, 100)
        ax.set_title("CPU Usage History")
        plt.setp(ax.get_xticklabels(), rotation=45, ha="right")
        hide_ticks(ax)
        return fig

    @output
    @render.data_frame
    def cpu_table():
        df = cpu_history()
        n = int(input.rows())
        if len(df) == 0:
            return pd.DataFrame(columns=["Timestamp", "CPU Usage"])
        return df.iloc[-n:][::-1].reset_index(drop=True)

app = App(app_ui, server)
